const unsoldDishes = `-- name: UnsoldDishes :many
SELECT c.id
FROM catalog_dishes c
WHERE c.id = ANY ($1::uuid[])
  AND (c.archived OR EXISTS (
      SELECT 1 FROM catalog_disabled_dishes d WHERE d.point_id = $2 AND d.dish_id = c.id))
`

type UnsoldDishesParams struct {
	DishIds []uuid.UUID
	PointID uuid.UUID
}

// Блюда из перечисленных, которые на точке не продаются: выключенные на ней или в архиве.
func (q *Queries) UnsoldDishes(ctx context.Context, arg UnsoldDishesParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, unsoldDishes, arg.DishIds, arg.PointID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

